export function generateSongCover(title, artist, colorA = '#2a1a12', colorB = '#d97706', isBollywood = false) {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 300">
    <defs>
      <linearGradient id="g" x1="0%" y1="0%" x2="100%" y2="100%">
        <stop offset="0%" stop-color="${colorA}"/>
        <stop offset="100%" stop-color="${colorB}"/>
      </linearGradient>
    </defs>
    <rect width="100%" height="100%" fill="url(#g)"/>
    <circle cx="150" cy="150" r="80" fill="none" stroke="rgba(255,255,255,0.12)" stroke-width="12"/>
    <circle cx="150" cy="150" r="40" fill="none" stroke="rgba(255,255,255,0.2)" stroke-width="6"/>
    <text x="150" y="260" font-family="system-ui, sans-serif" font-size="14" font-weight="bold" fill="rgba(255,255,255,0.9)" text-anchor="middle">${title.slice(0, 22)}</text>
  </svg>`;
  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;
}
